import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"分布式锁","description":"","frontmatter":{},"headers":[],"relativePath":"architect/distributed/basic/lock.md","filePath":"architect/distributed/basic/lock.md"}`),a={name:`architect/distributed/basic/lock.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="分布式锁" tabindex="-1">分布式锁 <a class="header-anchor" href="#分布式锁" aria-label="Permalink to “分布式锁”">​</a></h1><ul><li>线程锁： <blockquote><p>主要用来给方法、代码块加锁。当某个方法或代码使用锁，在同一时刻仅有一个线程执行该方法或该代码段。线程锁只在同一JVM中有效果，因为线程锁的实现在根本上是依靠线程之间共享内存实现的，比如synchronized是共享对象头，显示锁Lock是共享某个变量（state）。</p></blockquote></li><li>进程锁 <blockquote><p>为了控制同一操作系统中多个进程访问某个共享资源，因为进程具有独立性，各个进程无法访问其他进程的资源，因此无法通过synchronized等线程锁实现进程锁。</p></blockquote></li><li>分布式锁 <blockquote><p>当多个进程不在同一个系统中(比如分布式系统中控制共享资源访问)，用分布式锁控制多个进程对资源的访问。</p></blockquote></li></ul><h2 id="分布式锁的设计原则" tabindex="-1">分布式锁的设计原则 <a class="header-anchor" href="#分布式锁的设计原则" aria-label="Permalink to “分布式锁的设计原则”">​</a></h2><ul><li>互斥（属于安全性）: 在任何给定时刻，只有一个客户端可以持有锁。</li><li>无死锁（属于有效性）：即使锁定资源的客户端崩溃或被分区，也总是可以获得锁；通常通过超时机制实现。</li><li>容错性（属于有效性）：只要大多数 Redis 节点都启动，客户端就可以获取和释放锁。</li></ul><h2 id="分布式锁的实现方案" tabindex="-1">分布式锁的实现方案 <a class="header-anchor" href="#分布式锁的实现方案" aria-label="Permalink to “分布式锁的实现方案”">​</a></h2><ul><li>基于数据库实现分布式锁 <ul><li>基于数据库表（锁表，很少使用）</li><li>乐观锁(基于版本号)</li><li>悲观锁(基于排它锁)</li></ul></li><li>基于 redis 实现分布式锁 <ul><li>单个Redis实例：setnx(key,当前时间+过期时间) + Lua</li><li>Redis集群模式：Redlock</li></ul></li><li>基于 zookeeper实现分布式锁 <ul><li>临时有序节点来实现的分布式锁,Curator</li></ul></li><li>基于 Consul 实现分布式锁</li></ul>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};